"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[960],{770:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-09-pca-svd-mds</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-9-метод-главных-компонент-svd-и-многомерное-шкалирование">Лабораторная\nработа 9. Метод главных компонент, SVD и многомерное шкалирование</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 8, завершает курс</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 8: выборочная ковариационная матрица (опр. 8.1), первая\nглавная компонента (теорема 8.2), полная дисперсия (утв. 8.5), доля\nобъяснённой дисперсии, численный пример 8.7, сингулярное разложение\n(теорема 8.9), многомерное шкалирование</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно + домашняя работа (3–4 ч)</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Разобраться, что именно ищет PCA и почему ответ зависит от единиц\nизмерения; увидеть теорему Эккарта–Янга в действии на сжатии\nизображений; построить карту объектов по одним лишь попарным\nрасстояниям. Последняя часть — сводная по всему курсу.</p>\n<h2 id="как-устроено-занятие">Как устроено занятие</h2>\n<p>Ноутбук разбирается в аудитории: код запускается и обсуждается по\nходу. Большая часть ячеек уже написана — их нужно <strong>прочитать и\nзапустить</strong>, разобравшись, что происходит и почему.</p>\n<p>Ячейки, помеченные <code># ✍ ЗАДАНИЕ НА СЕМИНАРЕ</code>, заполняются\nсамостоятельно прямо на занятии; их немного, и каждая занимает несколько\nстрок. Ячейки <strong>Вывод</strong> — тоже ваши: короткий ответ своими\nсловами на поставленный вопрос.</p>\n<p>Дома выполняется отдельный ноутбук <code>lab09_homework.ipynb</code>\n— там задания крупнее и делать их нужно самому.</p>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже) — и на семинаре, и в домашней\nработе.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> load_digits, load_iris, load_wine</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.decomposition <span class="im">import</span> PCA</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LogisticRegression</span>\n<span id="cb1-49"><a href="#cb1-49" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> GridSearchCV, StratifiedKFold, cross_val_score</span>\n<span id="cb1-50"><a href="#cb1-50" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> Pipeline</span>\n<span id="cb1-51"><a href="#cb1-51" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb1-52"><a href="#cb1-52" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell002" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell003" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">9</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell004" class="cell markdown">\n<hr />\n<h1 id="часть-1-что-ищет-pca">Часть 1. Что ищет PCA</h1>\n<p>Определение 8.1: выборочная ковариационная матрица центрированных\nданных\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">C = \\frac1\\ell X^{\\mathsf T}X</annotation></semantics></math>.\nТеорема 8.2: первая главная компонента — это собственный вектор\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nс наибольшим собственным числом, а дисперсия проекции равна этому\nсобственному числу.</p>\n<p>Начнём с точного воспроизведения примера 8.7 из конспекта: четыре\nцентрированные точки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><mn>2</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(2,1)</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><mi>−</mi><mn>1</mn><mo>,</mo><mi>−</mi><mn>2</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(-1,-2)</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>,</mo><mn>2</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(1,2)</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><mi>−</mi><mn>2</mn><mo>,</mo><mi>−</mi><mn>1</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(-2,-1)</annotation></semantics></math>.\nТам получено\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo>=</mo><mn>4.5</mn></mrow><annotation encoding="application/x-tex">\\lambda = 4.5</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mn>0.5</mn><annotation encoding="application/x-tex">0.5</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>w</mi><mn>1</mn></msub><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo><mi>/</mi><msqrt><mn>2</mn></msqrt></mrow><annotation encoding="application/x-tex">w_1 = (1,1)/\\sqrt2</annotation></semantics></math>,\nдоля первой компоненты 90 %.</p>\n</div>\n<div id="cell005" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a>X_ex <span class="op">=</span> np.array([[<span class="fl">2.0</span>, <span class="fl">1.0</span>], [<span class="op">-</span><span class="fl">1.0</span>, <span class="op">-</span><span class="fl">2.0</span>], [<span class="fl">1.0</span>, <span class="fl">2.0</span>], [<span class="op">-</span><span class="fl">2.0</span>, <span class="op">-</span><span class="fl">1.0</span>]])</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;центр выборки:&quot;</span>, X_ex.mean(axis<span class="op">=</span><span class="dv">0</span>), <span class="st">&quot;(нулевой -- данные уже центрированы)&quot;</span>)</span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>C <span class="op">=</span> X_ex.T <span class="op">@</span> X_ex <span class="op">/</span> <span class="bu">len</span>(X_ex)                     <span class="co"># опр. 8.1</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;C =</span><span class="ch">\\n</span><span class="st">&quot;</span>, C)</span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;след Tr C = </span><span class="sc">{</span>np<span class="sc">.</span>trace(C)<span class="sc">}</span><span class="ss">, определитель = </span><span class="sc">{</span>np<span class="sc">.</span>linalg<span class="sc">.</span>det(C)<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell006" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co"> (3-4 строки): найдите собственные пары C через np.linalg.eigh,</span></span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a><span class="co">#   отсортируйте по УБЫВАНИЮ собственного числа и выведите:</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   собственные числа, первую компоненту и долю дисперсии lam[0]/sum(lam).</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">#   Сверьте с конспектом: 4.5 и 0.5, (1,1)/sqrt(2), доля 0.9.</span></span></code></pre></div>\n</div>\n<div id="cell007" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Утверждение 8.5: сумма собственных чисел = след C = полная дисперсия</span></span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;сумма собственных чисел = </span><span class="sc">{</span>lam<span class="sc">.</span><span class="bu">sum</span>()<span class="sc">:.4f}</span><span class="ss">, Tr C = </span><span class="sc">{</span>np<span class="sc">.</span>trace(C)<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="co"># Проекция на первую компоненту и восстановление</span></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a>w1 <span class="op">=</span> W[:, <span class="dv">0</span>] <span class="op">*</span> np.sign(W[<span class="dv">0</span>, <span class="dv">0</span>])</span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a>z <span class="op">=</span> X_ex <span class="op">@</span> w1</span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a>X_rec <span class="op">=</span> np.outer(z, w1)</span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="ch">\\n</span><span class="ss">проекции: </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">round</span>(z, <span class="dv">4</span>)<span class="sc">}</span><span class="ss">   (в конспекте +-3/sqrt(2) = +-</span><span class="sc">{</span><span class="dv">3</span> <span class="op">/</span> np<span class="sc">.</span>sqrt(<span class="dv">2</span>)<span class="sc">:.4f}</span><span class="ss">)&quot;</span>)</span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;восстановление x_1: </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">round</span>(X_rec[<span class="dv">0</span>], <span class="dv">4</span>)<span class="sc">}</span><span class="ss">   (в конспекте (1.5, 1.5))&quot;</span>)</span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;суммарная ошибка: </span><span class="sc">{</span>((X_ex <span class="op">-</span> X_rec) <span class="op">**</span> <span class="dv">2</span>)<span class="sc">.</span><span class="bu">sum</span>()<span class="sc">:.4f}</span><span class="ss">&quot;</span></span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;   (в конспекте lambda_2 * l = 0.5 * 4 = 2)&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell008" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпало ли с конспектом? Почему ошибка\nвосстановления равна в точности\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>λ</mi><mn>2</mn></msub><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">\\lambda_2\\ell</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell009" class="cell markdown">\n<hr />\n<h1 id="часть-2-масштабирование-меняет-ответ">Часть 2. Масштабирование\nменяет ответ</h1>\n<p>PCA ищет направления максимальной дисперсии, а дисперсия зависит от\nединиц измерения. Признак «доход в рублях» имеет дисперсию в миллиарды\nраз большую, чем «доля клиентов», и первая компонента совпадёт с ним\nпочти точно — независимо от содержательной важности.</p>\n</div>\n<div id="cell010" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a>X_w, y_w <span class="op">=</span> load_wine(return_X_y<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>feat <span class="op">=</span> np.array(load_wine().feature_names)</span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">2</span>, figsize<span class="op">=</span>(<span class="dv">13</span>, <span class="fl">4.6</span>))</span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax, (name, Xp) <span class="kw">in</span> <span class="bu">zip</span>(axes, [(<span class="st">&quot;без масштабирования&quot;</span>, X_w),</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a>                                 (<span class="st">&quot;StandardScaler&quot;</span>, StandardScaler().fit_transform(X_w))]):</span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a>    p <span class="op">=</span> PCA(n_components<span class="op">=</span><span class="dv">2</span>).fit(Xp)</span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a>    Z <span class="op">=</span> p.transform(Xp)</span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> c, mk <span class="kw">in</span> <span class="bu">zip</span>(<span class="bu">range</span>(<span class="dv">3</span>), <span class="st">&quot;os^&quot;</span>):</span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a>        ax.scatter(<span class="op">*</span>Z[y_w <span class="op">==</span> c].T, s<span class="op">=</span><span class="dv">18</span>, marker<span class="op">=</span>mk, label<span class="op">=</span><span class="ss">f&quot;класс </span><span class="sc">{</span>c<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a>    ax.set_xlabel(<span class="st">&quot;PC1&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="st">&quot;PC2&quot;</span>)<span class="op">;</span> ax.legend(fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a>    ax.set_title(<span class="ss">f&quot;</span><span class="sc">{</span>name<span class="sc">}</span><span class="ch">\\n</span><span class="ss">доля дисперсии PC1 = </span><span class="sc">{</span>p<span class="sc">.</span>explained_variance_ratio_[<span class="dv">0</span>]<span class="sc">:.3f}</span><span class="ss">&quot;</span>,</span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a>                 fontsize<span class="op">=</span><span class="dv">10</span>)</span>\n<span id="cb6-14"><a href="#cb6-14" aria-hidden="true" tabindex="-1"></a>    top <span class="op">=</span> np.<span class="bu">abs</span>(p.components_[<span class="dv">0</span>]).argsort()[::<span class="op">-</span><span class="dv">1</span>][:<span class="dv">3</span>]</span>\n<span id="cb6-15"><a href="#cb6-15" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">: PC1 объясняет </span><span class="sc">{</span>p<span class="sc">.</span>explained_variance_ratio_[<span class="dv">0</span>]<span class="sc">:.1%}</span><span class="ss">; главные вклады:&quot;</span>,</span>\n<span id="cb6-16"><a href="#cb6-16" aria-hidden="true" tabindex="-1"></a>          <span class="st">&quot;, &quot;</span>.join(<span class="ss">f&quot;</span><span class="sc">{</span>feat[t]<span class="sc">}</span><span class="ss"> (</span><span class="sc">{</span>p<span class="sc">.</span>components_[<span class="dv">0</span>][t]<span class="sc">:+.3f}</span><span class="ss">)&quot;</span> <span class="cf">for</span> t <span class="kw">in</span> top))</span>\n<span id="cb6-17"><a href="#cb6-17" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span>\n<span id="cb6-18"><a href="#cb6-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-19"><a href="#cb6-19" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;</span><span class="ch">\\n</span><span class="st">стандартные отклонения признаков:&quot;</span>)</span>\n<span id="cb6-20"><a href="#cb6-20" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(pd.Series(X_w.std(axis<span class="op">=</span><span class="dv">0</span>), index<span class="op">=</span>feat).sort_values(ascending<span class="op">=</span><span class="va">False</span>).head(<span class="dv">3</span>).<span class="bu">round</span>(<span class="dv">2</span>))</span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какой признак «захватил» первую компоненту\nбез масштабирования? Всегда ли нужно стандартизовать перед PCA?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell012" class="cell markdown">\n<hr />\n<h1 id="часть-3-сжатие-теорема-эккартаянга">Часть 3. Сжатие: теорема\nЭккарта–Янга</h1>\n<p>Следствие из теоремы 8.9: усечённое SVD ранга\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\n— <strong>наилучшее</strong> приближение матрицы рангом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nв норме Фробениуса, причём</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><munder><mi>min</mi><mrow><mrow><mi mathvariant="normal">r</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">k</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>B</mi><mo stretchy="false" form="postfix">)</mo><mo>≤</mo><mi>k</mi></mrow></munder><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mo>−</mo><mi>B</mi><msubsup><mo stretchy="false" form="postfix">∥</mo><mi>F</mi><mn>2</mn></msubsup><mspace width="0.278em"></mspace><mo>=</mo><mspace width="0.278em"></mspace><munder><mo>∑</mo><mrow><mi>j</mi><mo>&gt;</mo><mi>k</mi></mrow></munder><msubsup><mi>σ</mi><mi>j</mi><mn>2</mn></msubsup><mo>,</mo></mrow><annotation encoding="application/x-tex">\n\\min_{\\mathrm{rank}(B)\\le k}\\|X - B\\|_F^2 \\;=\\; \\sum_{j&gt;k}\\sigma_j^2 ,\n</annotation></semantics></math></p>\n<p>то есть ошибка равна сумме квадратов <strong>отброшенных</strong>\nсингулярных чисел.</p>\n</div>\n<div id="cell013" class="cell markdown">\n<blockquote>\n<p><strong>Напоминание — норма Фробениуса и ранг.</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>A</mi><msubsup><mo stretchy="false" form="postfix">∥</mo><mi>F</mi><mn>2</mn></msubsup><mo>=</mo><msub><mo>∑</mo><mrow><mi>i</mi><mo>,</mo><mi>j</mi></mrow></msub><msubsup><mi>a</mi><mrow><mi>i</mi><mi>j</mi></mrow><mn>2</mn></msubsup></mrow><annotation encoding="application/x-tex">\\|A\\|_F^2 = \\sum_{i,j}a_{ij}^2</annotation></semantics></math>\n— просто сумма квадратов всех элементов, то есть обычная евклидова\nнорма, если вытянуть матрицу в один вектор. В NumPy:\n<code>(A ** 2).sum()</code> или\n<code>np.linalg.norm(A, &quot;fro&quot;) ** 2</code>.</p>\n<p><strong>Ранг</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>B</mi><annotation encoding="application/x-tex">B</annotation></semantics></math>\nне превосходит\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nозначает, что все строки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>B</mi><annotation encoding="application/x-tex">B</annotation></semantics></math>\nлежат в некотором\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>-мерном\nподпространстве. Так что теорема Эккарта–Янга говорит буквально\nследующее: среди всех способов уложить данные в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nизмерений наилучший в смысле суммы квадратов ошибок — это усечённое SVD.\nПричём ошибка известна заранее, не надо ничего перебирать:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mo>∑</mo><mrow><mi>j</mi><mo>&gt;</mo><mi>k</mi></mrow></msub><msubsup><mi>σ</mi><mi>j</mi><mn>2</mn></msubsup></mrow><annotation encoding="application/x-tex">\\sum_{j&gt;k}\\sigma_j^2</annotation></semantics></math>.</p>\n</blockquote>\n</div>\n<div id="cell014" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>digits <span class="op">=</span> load_digits()</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>X_dig <span class="op">=</span> digits.data                        <span class="co"># 1797 изображений 8x8, значения 0..16</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>Xc <span class="op">=</span> X_dig <span class="op">-</span> X_dig.mean(axis<span class="op">=</span><span class="dv">0</span>)</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>U, s, Vt <span class="op">=</span> np.linalg.svd(Xc, full_matrices<span class="op">=</span><span class="va">False</span>)</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot; k   ||X - X_k||_F^2   сумма отброшенных sigma^2   расхождение&quot;</span>)</span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> k <span class="kw">in</span> [<span class="dv">1</span>, <span class="dv">5</span>, <span class="dv">10</span>, <span class="dv">20</span>, <span class="dv">40</span>]:</span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a>    Xk <span class="op">=</span> U[:, :k] <span class="op">@</span> np.diag(s[:k]) <span class="op">@</span> Vt[:k] <span class="op">+</span> X_dig.mean(axis<span class="op">=</span><span class="dv">0</span>)</span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a>    lhs, rhs <span class="op">=</span> ((X_dig <span class="op">-</span> Xk) <span class="op">**</span> <span class="dv">2</span>).<span class="bu">sum</span>(), (s[k:] <span class="op">**</span> <span class="dv">2</span>).<span class="bu">sum</span>()</span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>k<span class="sc">:3d}</span><span class="ss">   </span><span class="sc">{</span>lhs<span class="sc">:14.4f}</span><span class="ss">   </span><span class="sc">{</span>rhs<span class="sc">:24.4f}</span><span class="ss">   </span><span class="sc">{</span><span class="bu">abs</span>(lhs <span class="op">-</span> rhs)<span class="sc">:.2e}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell015" class="cell code">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a>ks <span class="op">=</span> [<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">4</span>, <span class="dv">8</span>, <span class="dv">16</span>, <span class="dv">32</span>, <span class="dv">64</span>]</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">3</span>, <span class="bu">len</span>(ks) <span class="op">+</span> <span class="dv">1</span>, figsize<span class="op">=</span>(<span class="fl">1.5</span> <span class="op">*</span> (<span class="bu">len</span>(ks) <span class="op">+</span> <span class="dv">1</span>), <span class="fl">4.8</span>))</span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> r, i <span class="kw">in</span> <span class="bu">enumerate</span>([<span class="dv">0</span>, <span class="dv">1</span>, <span class="dv">2</span>]):</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>    axes[r, <span class="dv">0</span>].imshow(X_dig[i].reshape(<span class="dv">8</span>, <span class="dv">8</span>), cmap<span class="op">=</span><span class="st">&quot;gray_r&quot;</span>)</span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a>    axes[r, <span class="dv">0</span>].set_ylabel(<span class="ss">f&quot;цифра </span><span class="sc">{</span>digits<span class="sc">.</span>target[i]<span class="sc">}</span><span class="ss">&quot;</span>, fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a>    axes[r, <span class="dv">0</span>].set_xticks([])<span class="op">;</span> axes[r, <span class="dv">0</span>].set_yticks([])</span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">if</span> r <span class="op">==</span> <span class="dv">0</span>:</span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a>        axes[r, <span class="dv">0</span>].set_title(<span class="st">&quot;оригинал&quot;</span>, fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> c, k <span class="kw">in</span> <span class="bu">enumerate</span>(ks, start<span class="op">=</span><span class="dv">1</span>):</span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a>    p <span class="op">=</span> PCA(n_components<span class="op">=</span>k).fit(X_dig)</span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a>    rec <span class="op">=</span> p.inverse_transform(p.transform(X_dig))</span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> r, i <span class="kw">in</span> <span class="bu">enumerate</span>([<span class="dv">0</span>, <span class="dv">1</span>, <span class="dv">2</span>]):</span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a>        axes[r, c].imshow(rec[i].reshape(<span class="dv">8</span>, <span class="dv">8</span>), cmap<span class="op">=</span><span class="st">&quot;gray_r&quot;</span>)</span>\n<span id="cb8-14"><a href="#cb8-14" aria-hidden="true" tabindex="-1"></a>        axes[r, c].set_xticks([])<span class="op">;</span> axes[r, c].set_yticks([])</span>\n<span id="cb8-15"><a href="#cb8-15" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> r <span class="op">==</span> <span class="dv">0</span>:</span>\n<span id="cb8-16"><a href="#cb8-16" aria-hidden="true" tabindex="-1"></a>            axes[r, c].set_title(<span class="ss">f&quot;$k=</span><span class="sc">{</span>k<span class="sc">}</span><span class="ss">$</span><span class="ch">\\n</span><span class="sc">{</span>p<span class="sc">.</span>explained_variance_ratio_<span class="sc">.</span><span class="bu">sum</span>()<span class="sc">:.0%}</span><span class="ss">&quot;</span>,</span>\n<span id="cb8-17"><a href="#cb8-17" aria-hidden="true" tabindex="-1"></a>                                 fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb8-18"><a href="#cb8-18" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span>\n<span id="cb8-19"><a href="#cb8-19" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-20"><a href="#cb8-20" aria-hidden="true" tabindex="-1"></a>cum_dig <span class="op">=</span> np.cumsum(PCA().fit(X_dig).explained_variance_ratio_)</span>\n<span id="cb8-21"><a href="#cb8-21" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;для 90% дисперсии достаточно </span><span class="sc">{</span><span class="bu">int</span>(np.searchsorted(cum_dig, <span class="fl">0.90</span>) <span class="op">+</span> <span class="dv">1</span>)<span class="sc">}</span><span class="ss"> компонент из 64&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell016" class="cell code">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="co"># «Собственные цифры»: первые компоненты как изображения</span></span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a>p19 <span class="op">=</span> PCA(n_components<span class="op">=</span><span class="dv">19</span>).fit(X_dig)</span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">2</span>, <span class="dv">10</span>, figsize<span class="op">=</span>(<span class="dv">14</span>, <span class="fl">3.2</span>))</span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>, <span class="dv">0</span>].imshow(p19.mean_.reshape(<span class="dv">8</span>, <span class="dv">8</span>), cmap<span class="op">=</span><span class="st">&quot;gray_r&quot;</span>)</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>, <span class="dv">0</span>].set_title(<span class="st">&quot;среднее&quot;</span>, fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> j, ax <span class="kw">in</span> <span class="bu">enumerate</span>(np.ravel(axes)[<span class="dv">1</span>:<span class="dv">20</span>]):</span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a>    ax.imshow(p19.components_[j].reshape(<span class="dv">8</span>, <span class="dv">8</span>), cmap<span class="op">=</span><span class="st">&quot;RdBu_r&quot;</span>)</span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a>    ax.set_title(<span class="ss">f&quot;PC</span><span class="sc">{</span>j <span class="op">+</span> <span class="dv">1</span><span class="sc">}</span><span class="ch">\\n</span><span class="sc">{</span>p19<span class="sc">.</span>explained_variance_ratio_[j]<span class="sc">:.1%}</span><span class="ss">&quot;</span>, fontsize<span class="op">=</span><span class="dv">7</span>)</span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax <span class="kw">in</span> np.ravel(axes):</span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a>    ax.set_xticks([])<span class="op">;</span> ax.set_yticks([])</span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a>fig.suptitle(<span class="st">&quot;Главные компоненты изображений&quot;</span>)</span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell017" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпала ли ошибка восстановления с суммой\nотброшенных\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msubsup><mi>σ</mi><mi>j</mi><mn>2</mn></msubsup><annotation encoding="application/x-tex">\\sigma_j^2</annotation></semantics></math>?\nПри каком\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nцифры узнаваемы и что изображают первые компоненты?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell018" class="cell markdown">\n<hr />\n<h1 id="часть-4-pca-как-предобработка">Часть 4. PCA как\nпредобработка</h1>\n<p>Снижение размерности перед обучением — компромисс: теряем часть\nинформации, но уменьшаем разброс (занятие 5) и ускоряем обучение. Важно,\nчто PCA <strong>не использует метки</strong> — он максимизирует\nдисперсию, а не разделимость классов.</p>\n<p>И конечно, PCA должен быть шагом <code>Pipeline</code>: иначе главные\nкомпоненты считаются по всей выборке, включая контрольную, — это утечка\nиз занятия 5.</p>\n</div>\n<div id="cell019" class="cell code">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a>X_d, y_d <span class="op">=</span> load_digits(return_X_y<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a>cv9 <span class="op">=</span> StratifiedKFold(<span class="dv">5</span>, shuffle<span class="op">=</span><span class="va">True</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> k <span class="kw">in</span> [<span class="dv">2</span>, <span class="dv">5</span>, <span class="dv">10</span>, <span class="dv">20</span>, <span class="dv">30</span>, <span class="dv">40</span>, <span class="dv">64</span>]:</span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a>    pipe <span class="op">=</span> Pipeline([(<span class="st">&quot;scale&quot;</span>, StandardScaler()), (<span class="st">&quot;pca&quot;</span>, PCA(n_components<span class="op">=</span>k)),</span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a>                     (<span class="st">&quot;clf&quot;</span>, LogisticRegression(max_iter<span class="op">=</span><span class="dv">3000</span>))])</span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;компонент&quot;</span>: k, <span class="st">&quot;точность&quot;</span>: cross_val_score(pipe, X_d, y_d, cv<span class="op">=</span>cv9).mean()})</span>\n<span id="cb10-9"><a href="#cb10-9" aria-hidden="true" tabindex="-1"></a>base <span class="op">=</span> cross_val_score(Pipeline([(<span class="st">&quot;scale&quot;</span>, StandardScaler()),</span>\n<span id="cb10-10"><a href="#cb10-10" aria-hidden="true" tabindex="-1"></a>                                 (<span class="st">&quot;clf&quot;</span>, LogisticRegression(max_iter<span class="op">=</span><span class="dv">3000</span>))]),</span>\n<span id="cb10-11"><a href="#cb10-11" aria-hidden="true" tabindex="-1"></a>                       X_d, y_d, cv<span class="op">=</span>cv9).mean()</span>\n<span id="cb10-12"><a href="#cb10-12" aria-hidden="true" tabindex="-1"></a>display(pd.DataFrame(rows).set_index(<span class="st">&quot;компонент&quot;</span>).<span class="bu">round</span>(<span class="dv">4</span>))</span>\n<span id="cb10-13"><a href="#cb10-13" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;без PCA (все 64 признака): </span><span class="sc">{</span>base<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell020" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.feature_selection <span class="im">import</span> SelectKBest, f_classif</span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>)     <span class="co"># у digits есть всегда-чёрные пиксели: f_classif делит на 0</span></span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co"> (3-4 строки): для k in [2, 5, 10, 20, 30] сравните два конвейера</span></span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a><span class="co">#   при одинаковом числе признаков:</span></span>\n<span id="cb11-9"><a href="#cb11-9" aria-hidden="true" tabindex="-1"></a><span class="co">#     StandardScaler -&gt; PCA(k)                    -&gt; LogisticRegression</span></span>\n<span id="cb11-10"><a href="#cb11-10" aria-hidden="true" tabindex="-1"></a><span class="co">#     StandardScaler -&gt; SelectKBest(f_classif, k) -&gt; LogisticRegression</span></span>\n<span id="cb11-11"><a href="#cb11-11" aria-hidden="true" tabindex="-1"></a><span class="co">#   Оценивайте cross_val_score(..., cv=cv9). Кто лучше при малом k?</span></span></code></pre></div>\n</div>\n<div id="cell021" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Сколько компонент достаточно, чтобы не\nпотерять качество? Кто лучше при малом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\n— PCA или отбор признаков, и почему?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell022" class="cell markdown">\n<hr />\n<h1 id="часть-5-карта-по-одним-лишь-расстояниям">Часть 5. Карта по одним\nлишь расстояниям</h1>\n<p>Иногда координат нет вовсе — есть только матрица попарных несходств:\nэкспертные оценки, генетические дистанции, время в пути. Многомерное\nшкалирование восстанавливает по ней координаты.</p>\n<p>Классическое MDS (§5 лекции 8): по матрице квадратов расстояний\nдвойным центрированием восстанавливается матрица Грама\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mo>=</mo><mi>−</mi><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>J</mi><msup><mi>D</mi><mrow><mo stretchy="false" form="prefix">(</mo><mn>2</mn><mo stretchy="false" form="postfix">)</mo></mrow></msup><mi>J</mi></mrow><annotation encoding="application/x-tex">B = -\\frac12 J D^{(2)} J</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>J</mi><mo>=</mo><mi>I</mi><mo>−</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><mn>𝟏</mn><msup><mn>𝟏</mn><mi>𝖳</mi></msup></mrow><annotation encoding="application/x-tex">J = I - \\frac1\\ell\\mathbf1\\mathbf1^{\\mathsf T}</annotation></semantics></math>,\nа координаты берутся из\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nстарших собственных пар\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>B</mi><annotation encoding="application/x-tex">B</annotation></semantics></math>.</p>\n</div>\n<div id="cell023" class="cell markdown">\n<blockquote>\n<p><strong>Напоминание — матрица Грама и диаграмма Шепарда.</strong>\n<strong>Матрица Грама</strong> — матрица попарных скалярных\nпроизведений,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>B</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>=</mo><mo stretchy="false" form="prefix">⟨</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>x</mi><mi>j</mi></msub><mo stretchy="false" form="postfix">⟩</mo></mrow><annotation encoding="application/x-tex">B_{ij} = \\langle x_i, x_j\\rangle</annotation></semantics></math>.\nКлюч ко всему методу — тождество\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>x</mi><mi>j</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>=</mo><msub><mi>B</mi><mrow><mi>i</mi><mi>i</mi></mrow></msub><mo>−</mo><mn>2</mn><msub><mi>B</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>+</mo><msub><mi>B</mi><mrow><mi>j</mi><mi>j</mi></mrow></msub></mrow><annotation encoding="application/x-tex">\\|x_i-x_j\\|^2 = B_{ii} - 2B_{ij} + B_{jj}</annotation></semantics></math>:\nрасстояния выражаются через скалярные произведения, и наоборот — если\nзафиксировать начало координат в центре выборки, то по расстояниям\nоднозначно восстанавливаются скалярные произведения. Это и делает\nдвойное центрирование. Дальше\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mo>=</mo><mi>Z</mi><msup><mi>Z</mi><mi>𝖳</mi></msup></mrow><annotation encoding="application/x-tex">B = ZZ^{\\mathsf T}</annotation></semantics></math>\nдаёт координаты\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Z</mi><annotation encoding="application/x-tex">Z</annotation></semantics></math>\n— с точностью до поворота и отражения, потому что они скалярных\nпроизведений не меняют.</p>\n<p><strong>Диаграмма Шепарда</strong> — проверка качества вложения: по\nгоризонтали исходные несходства, по вертикали расстояния на построенной\nкарте, по одной точке на пару объектов. Идеальному вложению отвечает\nбиссектриса; систематический изгиб означает, что размерности не\nхватило.</p>\n</blockquote>\n</div>\n<div id="cell024" class="cell code">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a>cities <span class="op">=</span> [<span class="st">&quot;Калининград&quot;</span>, <span class="st">&quot;Санкт-Петербург&quot;</span>, <span class="st">&quot;Москва&quot;</span>, <span class="st">&quot;Ростов-на-Дону&quot;</span>,</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a>          <span class="st">&quot;Казань&quot;</span>, <span class="st">&quot;Екатеринбург&quot;</span>, <span class="st">&quot;Новосибирск&quot;</span>, <span class="st">&quot;Иркутск&quot;</span>, <span class="st">&quot;Владивосток&quot;</span>]</span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a>D_km <span class="op">=</span> np.array([</span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a>    [   <span class="dv">0</span>,  <span class="dv">800</span>, <span class="dv">1090</span>, <span class="dv">1650</span>, <span class="dv">1780</span>, <span class="dv">2380</span>, <span class="dv">3760</span>, <span class="dv">5350</span>, <span class="dv">7900</span>],</span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a>    [ <span class="dv">800</span>,    <span class="dv">0</span>,  <span class="dv">635</span>, <span class="dv">1520</span>, <span class="dv">1330</span>, <span class="dv">1780</span>, <span class="dv">3110</span>, <span class="dv">4700</span>, <span class="dv">6400</span>],</span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">1090</span>,  <span class="dv">635</span>,    <span class="dv">0</span>,  <span class="dv">960</span>,  <span class="dv">720</span>, <span class="dv">1420</span>, <span class="dv">2810</span>, <span class="dv">4200</span>, <span class="dv">6430</span>],</span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">1650</span>, <span class="dv">1520</span>,  <span class="dv">960</span>,    <span class="dv">0</span>,  <span class="dv">980</span>, <span class="dv">1750</span>, <span class="dv">3100</span>, <span class="dv">4500</span>, <span class="dv">6800</span>],</span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">1780</span>, <span class="dv">1330</span>,  <span class="dv">720</span>,  <span class="dv">980</span>,    <span class="dv">0</span>,  <span class="dv">730</span>, <span class="dv">2100</span>, <span class="dv">3500</span>, <span class="dv">5750</span>],</span>\n<span id="cb12-9"><a href="#cb12-9" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">2380</span>, <span class="dv">1780</span>, <span class="dv">1420</span>, <span class="dv">1750</span>,  <span class="dv">730</span>,    <span class="dv">0</span>, <span class="dv">1400</span>, <span class="dv">2800</span>, <span class="dv">5050</span>],</span>\n<span id="cb12-10"><a href="#cb12-10" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">3760</span>, <span class="dv">3110</span>, <span class="dv">2810</span>, <span class="dv">3100</span>, <span class="dv">2100</span>, <span class="dv">1400</span>,    <span class="dv">0</span>, <span class="dv">1450</span>, <span class="dv">3700</span>],</span>\n<span id="cb12-11"><a href="#cb12-11" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">5350</span>, <span class="dv">4700</span>, <span class="dv">4200</span>, <span class="dv">4500</span>, <span class="dv">3500</span>, <span class="dv">2800</span>, <span class="dv">1450</span>,    <span class="dv">0</span>, <span class="dv">2500</span>],</span>\n<span id="cb12-12"><a href="#cb12-12" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">7900</span>, <span class="dv">6400</span>, <span class="dv">6430</span>, <span class="dv">6800</span>, <span class="dv">5750</span>, <span class="dv">5050</span>, <span class="dv">3700</span>, <span class="dv">2500</span>,    <span class="dv">0</span>]], dtype<span class="op">=</span><span class="bu">float</span>)</span>\n<span id="cb12-13"><a href="#cb12-13" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;координат нет -- только попарные расстояния по прямой, км&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell025" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> classic_mds(D, k<span class="op">=</span><span class="dv">2</span>):</span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Классическое MDS.</span></span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a><span class="co">    1) J = I - (1/l) * матрица из единиц;</span></span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a><span class="co">    2) B = -1/2 * J @ D^2 @ J   (двойное центрирование);</span></span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a><span class="co">    3) собственные пары B (np.linalg.eigh), взять k старших;</span></span>\n<span id="cb13-9"><a href="#cb13-9" aria-hidden="true" tabindex="-1"></a><span class="co">    4) координаты = U_k * sqrt(lambda_k), отрицательные lambda обнулить.</span></span>\n<span id="cb13-10"><a href="#cb13-10" aria-hidden="true" tabindex="-1"></a><span class="co">    Возвращает (координаты, спектр по убыванию).</span></span>\n<span id="cb13-11"><a href="#cb13-11" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb13-12"><a href="#cb13-12" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb13-13"><a href="#cb13-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-14"><a href="#cb13-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-15"><a href="#cb13-15" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: восстановите координаты по D_km, посчитайте среднюю ошибку</span></span>\n<span id="cb13-16"><a href="#cb13-16" aria-hidden="true" tabindex="-1"></a><span class="co">#       воспроизведения расстояний и долю первых двух собственных чисел.</span></span></code></pre></div>\n</div>\n<div id="cell026" class="cell code">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a>xs, ys <span class="op">=</span> coords[:, <span class="dv">0</span>], coords[:, <span class="dv">1</span>]</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a><span class="cf">if</span> xs[cities.index(<span class="st">&quot;Владивосток&quot;</span>)] <span class="op">&lt;</span> xs[cities.index(<span class="st">&quot;Калининград&quot;</span>)]:</span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a>    xs <span class="op">=</span> <span class="op">-</span>xs                                    <span class="co"># разворот: восток направо</span></span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a>fig, (ax1, ax2) <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">2</span>, figsize<span class="op">=</span>(<span class="dv">13</span>, <span class="dv">5</span>))</span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a>ax1.scatter(xs, ys, s<span class="op">=</span><span class="dv">60</span>, color<span class="op">=</span><span class="st">&quot;#128C7E&quot;</span>)</span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> nm, a, b <span class="kw">in</span> <span class="bu">zip</span>(cities, xs, ys):</span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a>    ax1.annotate(nm, (a, b), fontsize<span class="op">=</span><span class="dv">8</span>, xytext<span class="op">=</span>(<span class="dv">4</span>, <span class="dv">4</span>), textcoords<span class="op">=</span><span class="st">&quot;offset points&quot;</span>)</span>\n<span id="cb14-9"><a href="#cb14-9" aria-hidden="true" tabindex="-1"></a>ax1.set_xlabel(<span class="st">&quot;MDS-1&quot;</span>)<span class="op">;</span> ax1.set_ylabel(<span class="st">&quot;MDS-2&quot;</span>)<span class="op">;</span> ax1.set_aspect(<span class="st">&quot;equal&quot;</span>)</span>\n<span id="cb14-10"><a href="#cb14-10" aria-hidden="true" tabindex="-1"></a>ax1.set_title(<span class="st">&quot;Карта, восстановленная по одним лишь расстояниям&quot;</span>)</span>\n<span id="cb14-11"><a href="#cb14-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-12"><a href="#cb14-12" aria-hidden="true" tabindex="-1"></a>ax2.scatter(D_km[iu], D_rec[iu], s<span class="op">=</span><span class="dv">28</span>, color<span class="op">=</span><span class="st">&quot;#C97A2B&quot;</span>)</span>\n<span id="cb14-13"><a href="#cb14-13" aria-hidden="true" tabindex="-1"></a>ax2.plot([<span class="dv">0</span>, D_km.<span class="bu">max</span>()], [<span class="dv">0</span>, D_km.<span class="bu">max</span>()], <span class="st">&quot;k--&quot;</span>, lw<span class="op">=</span><span class="dv">1</span>)</span>\n<span id="cb14-14"><a href="#cb14-14" aria-hidden="true" tabindex="-1"></a>ax2.set_xlabel(<span class="st">&quot;истинное расстояние, км&quot;</span>)<span class="op">;</span> ax2.set_ylabel(<span class="st">&quot;расстояние на карте&quot;</span>)</span>\n<span id="cb14-15"><a href="#cb14-15" aria-hidden="true" tabindex="-1"></a>ax2.set_title(<span class="st">&quot;Диаграмма Шепарда&quot;</span>)</span>\n<span id="cb14-16"><a href="#cb14-16" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell027" class="cell code">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="co"># При евклидовой метрике классическое MDS и PCA -- одно и то же вычисление</span></span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a>X_i <span class="op">=</span> StandardScaler().fit_transform(load_iris(return_X_y<span class="op">=</span><span class="va">True</span>)[<span class="dv">0</span>])</span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a>sq <span class="op">=</span> (X_i <span class="op">**</span> <span class="dv">2</span>).<span class="bu">sum</span>(axis<span class="op">=</span><span class="dv">1</span>)</span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a>D_i <span class="op">=</span> np.sqrt(np.maximum(sq[:, <span class="va">None</span>] <span class="op">-</span> <span class="dv">2</span> <span class="op">*</span> X_i <span class="op">@</span> X_i.T <span class="op">+</span> sq[<span class="va">None</span>, :], <span class="dv">0</span>))</span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a>Z_pca <span class="op">=</span> PCA(n_components<span class="op">=</span><span class="dv">2</span>).fit_transform(X_i)</span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a>Z_mds, _ <span class="op">=</span> classic_mds(D_i, k<span class="op">=</span><span class="dv">2</span>)</span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a>dist <span class="op">=</span> <span class="kw">lambda</span> Z: np.sqrt(np.maximum(((Z[:, <span class="va">None</span>] <span class="op">-</span> Z[<span class="va">None</span>]) <span class="op">**</span> <span class="dv">2</span>).<span class="bu">sum</span>(<span class="op">-</span><span class="dv">1</span>), <span class="dv">0</span>))</span>\n<span id="cb15-9"><a href="#cb15-9" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;max|расстояния PCA - расстояния MDS| = </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">abs</span>(dist(Z_pca) <span class="op">-</span> dist(Z_mds))<span class="sc">.</span><span class="bu">max</span>()<span class="sc">:.2e}</span><span class="ss">&quot;</span>)</span>\n<span id="cb15-10"><a href="#cb15-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;=&gt; одна и та же конфигурация (с точностью до поворота и отражения)&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell028" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Насколько точно восстановилась карта? Почему\nMDS и PCA совпали и в какой ситуации MDS применим, а PCA — нет?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell029" class="cell markdown">\n<hr />\n<h1 id="часть-6-сводная-полный-цикл-на-своей-выборке">Часть 6. Сводная:\nполный цикл на своей выборке</h1>\n<p>Заключительная часть курса. Проходим весь путь: предобработка\n(занятие 1), снижение размерности, сравнение моделей из разных семейств\nс подбором гиперпараметров по скользящему контролю (занятие 5), честная\nфинальная оценка и интерпретация.</p>\n</div>\n<div id="cell030" class="cell markdown">\n<blockquote>\n<p><strong>Напоминание — scree-plot и правило локтя.</strong>\n<strong>Scree-plot</strong> («осыпь») — график собственных чисел\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>λ</mi><mi>j</mi></msub><annotation encoding="application/x-tex">\\lambda_j</annotation></semantics></math>\nпо убыванию номера компоненты. Название геологическое: крутой склон из\nкрупных компонент и пологая осыпь мелочи у подножия. <strong>Правило\nлоктя</strong> — взять\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nв точке излома, где крутое падение сменяется пологим: считается, что\nдальше идёт шум.</p>\n<p>Правило неформальное — излома может не быть вовсе, и тогда решают по\nдоле объяснённой дисперсии или, что честнее, по качеству итоговой модели\n(это домашняя работа). Численно излом ищут как максимум второй разности\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>λ</mi><mrow><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>−</mo><mn>2</mn><msub><mi>λ</mi><mi>j</mi></msub><mo>+</mo><msub><mi>λ</mi><mrow><mi>j</mi><mo>+</mo><mn>1</mn></mrow></msub></mrow><annotation encoding="application/x-tex">\\lambda_{j-1} - 2\\lambda_j + \\lambda_{j+1}</annotation></semantics></math>.</p>\n</blockquote>\n</div>\n<div id="cell031" class="cell code">\n<div class="sourceCode" id="cb16"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb16-1"><a href="#cb16-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.ensemble <span class="im">import</span> RandomForestClassifier</span>\n<span id="cb16-2"><a href="#cb16-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> roc_auc_score</span>\n<span id="cb16-3"><a href="#cb16-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.neighbors <span class="im">import</span> KNeighborsClassifier</span>\n<span id="cb16-4"><a href="#cb16-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-5"><a href="#cb16-5" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb16-6"><a href="#cb16-6" aria-hidden="true" tabindex="-1"></a>Xtr, Xte, ytr, yte <span class="op">=</span> data[<span class="st">&quot;X_train&quot;</span>], data[<span class="st">&quot;X_test&quot;</span>], data[<span class="st">&quot;y_train&quot;</span>], data[<span class="st">&quot;y_test&quot;</span>]</span>\n<span id="cb16-7"><a href="#cb16-7" aria-hidden="true" tabindex="-1"></a><span class="cf">if</span> data[<span class="st">&quot;task&quot;</span>] <span class="op">==</span> <span class="st">&quot;regression&quot;</span>:</span>\n<span id="cb16-8"><a href="#cb16-8" aria-hidden="true" tabindex="-1"></a>    thr <span class="op">=</span> np.median(ytr)</span>\n<span id="cb16-9"><a href="#cb16-9" aria-hidden="true" tabindex="-1"></a>    ytr, yte <span class="op">=</span> (ytr <span class="op">&gt;</span> thr).astype(<span class="bu">int</span>), (yte <span class="op">&gt;</span> thr).astype(<span class="bu">int</span>)</span>\n<span id="cb16-10"><a href="#cb16-10" aria-hidden="true" tabindex="-1"></a>ytr, yte <span class="op">=</span> np.asarray(ytr).astype(<span class="bu">int</span>), np.asarray(yte).astype(<span class="bu">int</span>)</span>\n<span id="cb16-11"><a href="#cb16-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-12"><a href="#cb16-12" aria-hidden="true" tabindex="-1"></a>p_full <span class="op">=</span> PCA().fit(Xtr)</span>\n<span id="cb16-13"><a href="#cb16-13" aria-hidden="true" tabindex="-1"></a>cum <span class="op">=</span> np.cumsum(p_full.explained_variance_ratio_)</span>\n<span id="cb16-14"><a href="#cb16-14" aria-hidden="true" tabindex="-1"></a>rule <span class="op">=</span> variant[<span class="st">&quot;n_components_rule&quot;</span>]</span>\n<span id="cb16-15"><a href="#cb16-15" aria-hidden="true" tabindex="-1"></a><span class="cf">if</span> <span class="st">&quot;95&quot;</span> <span class="kw">in</span> rule:</span>\n<span id="cb16-16"><a href="#cb16-16" aria-hidden="true" tabindex="-1"></a>    k_var <span class="op">=</span> <span class="bu">int</span>(np.searchsorted(cum, <span class="fl">0.95</span>) <span class="op">+</span> <span class="dv">1</span>)</span>\n<span id="cb16-17"><a href="#cb16-17" aria-hidden="true" tabindex="-1"></a><span class="cf">elif</span> <span class="st">&quot;90&quot;</span> <span class="kw">in</span> rule:</span>\n<span id="cb16-18"><a href="#cb16-18" aria-hidden="true" tabindex="-1"></a>    k_var <span class="op">=</span> <span class="bu">int</span>(np.searchsorted(cum, <span class="fl">0.90</span>) <span class="op">+</span> <span class="dv">1</span>)</span>\n<span id="cb16-19"><a href="#cb16-19" aria-hidden="true" tabindex="-1"></a><span class="cf">else</span>:                                    <span class="co"># правило локтя: максимум второй разности</span></span>\n<span id="cb16-20"><a href="#cb16-20" aria-hidden="true" tabindex="-1"></a>    k_var <span class="op">=</span> <span class="bu">int</span>(np.argmax(np.diff(p_full.explained_variance_, <span class="dv">2</span>)) <span class="op">+</span> <span class="dv">2</span>)</span>\n<span id="cb16-21"><a href="#cb16-21" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;признаков после предобработки: </span><span class="sc">{</span>Xtr<span class="sc">.</span>shape[<span class="dv">1</span>]<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb16-22"><a href="#cb16-22" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;ваше правило «</span><span class="sc">{</span>rule<span class="sc">}</span><span class="ss">» -&gt; k = </span><span class="sc">{</span>k_var<span class="sc">}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell032" class="cell code">\n<div class="sourceCode" id="cb17"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb17-1"><a href="#cb17-1" aria-hidden="true" tabindex="-1"></a>Z2 <span class="op">=</span> PCA(n_components<span class="op">=</span><span class="dv">2</span>).fit_transform(Xtr)</span>\n<span id="cb17-2"><a href="#cb17-2" aria-hidden="true" tabindex="-1"></a>fig, (ax1, ax2) <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">2</span>, figsize<span class="op">=</span>(<span class="dv">12</span>, <span class="fl">4.6</span>))</span>\n<span id="cb17-3"><a href="#cb17-3" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> c, mk <span class="kw">in</span> <span class="bu">zip</span>([<span class="dv">0</span>, <span class="dv">1</span>], <span class="st">&quot;os&quot;</span>):</span>\n<span id="cb17-4"><a href="#cb17-4" aria-hidden="true" tabindex="-1"></a>    ax1.scatter(<span class="op">*</span>Z2[ytr <span class="op">==</span> c].T, s<span class="op">=</span><span class="dv">14</span>, marker<span class="op">=</span>mk, alpha<span class="op">=</span><span class="fl">0.6</span>, label<span class="op">=</span><span class="ss">f&quot;класс </span><span class="sc">{</span>c<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb17-5"><a href="#cb17-5" aria-hidden="true" tabindex="-1"></a>ax1.set_xlabel(<span class="st">&quot;PC1&quot;</span>)<span class="op">;</span> ax1.set_ylabel(<span class="st">&quot;PC2&quot;</span>)<span class="op">;</span> ax1.legend(fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb17-6"><a href="#cb17-6" aria-hidden="true" tabindex="-1"></a>ax1.set_title(<span class="st">&quot;Выборка в первых двух главных компонентах&quot;</span>)</span>\n<span id="cb17-7"><a href="#cb17-7" aria-hidden="true" tabindex="-1"></a>ax2.plot(np.arange(<span class="dv">1</span>, <span class="bu">len</span>(cum) <span class="op">+</span> <span class="dv">1</span>), cum, <span class="st">&quot;o-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>)</span>\n<span id="cb17-8"><a href="#cb17-8" aria-hidden="true" tabindex="-1"></a>ax2.axvline(k_var, ls<span class="op">=</span><span class="st">&quot;--&quot;</span>, color<span class="op">=</span><span class="st">&quot;#C97A2B&quot;</span>, label<span class="op">=</span><span class="ss">f&quot;ваше правило: $k = </span><span class="sc">{</span>k_var<span class="sc">}</span><span class="ss">$&quot;</span>)</span>\n<span id="cb17-9"><a href="#cb17-9" aria-hidden="true" tabindex="-1"></a>ax2.set_xlabel(<span class="st">&quot;число компонент&quot;</span>)<span class="op">;</span> ax2.set_ylabel(<span class="st">&quot;накопленная доля дисперсии&quot;</span>)</span>\n<span id="cb17-10"><a href="#cb17-10" aria-hidden="true" tabindex="-1"></a>ax2.legend(fontsize<span class="op">=</span><span class="dv">8</span>)<span class="op">;</span> ax2.set_title(<span class="st">&quot;Выбор числа компонент&quot;</span>)</span>\n<span id="cb17-11"><a href="#cb17-11" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell033" class="cell code">\n<div class="sourceCode" id="cb18"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb18-1"><a href="#cb18-1" aria-hidden="true" tabindex="-1"></a>cvf <span class="op">=</span> StratifiedKFold(<span class="dv">5</span>, shuffle<span class="op">=</span><span class="va">True</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb18-2"><a href="#cb18-2" aria-hidden="true" tabindex="-1"></a>candidates <span class="op">=</span> {</span>\n<span id="cb18-3"><a href="#cb18-3" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;линейная (логистическая регрессия)&quot;</span>:</span>\n<span id="cb18-4"><a href="#cb18-4" aria-hidden="true" tabindex="-1"></a>        (Pipeline([(<span class="st">&quot;pca&quot;</span>, PCA()), (<span class="st">&quot;clf&quot;</span>, LogisticRegression(max_iter<span class="op">=</span><span class="dv">5000</span>))]),</span>\n<span id="cb18-5"><a href="#cb18-5" aria-hidden="true" tabindex="-1"></a>         {<span class="st">&quot;pca__n_components&quot;</span>: [k_var, Xtr.shape[<span class="dv">1</span>]], <span class="st">&quot;clf__C&quot;</span>: np.logspace(<span class="op">-</span><span class="dv">2</span>, <span class="dv">2</span>, <span class="dv">5</span>)}),</span>\n<span id="cb18-6"><a href="#cb18-6" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;метрическая (kNN)&quot;</span>:</span>\n<span id="cb18-7"><a href="#cb18-7" aria-hidden="true" tabindex="-1"></a>        (Pipeline([(<span class="st">&quot;pca&quot;</span>, PCA()), (<span class="st">&quot;clf&quot;</span>, KNeighborsClassifier())]),</span>\n<span id="cb18-8"><a href="#cb18-8" aria-hidden="true" tabindex="-1"></a>         {<span class="st">&quot;pca__n_components&quot;</span>: [k_var, Xtr.shape[<span class="dv">1</span>]], <span class="st">&quot;clf__n_neighbors&quot;</span>: [<span class="dv">3</span>, <span class="dv">7</span>, <span class="dv">15</span>, <span class="dv">31</span>]}),</span>\n<span id="cb18-9"><a href="#cb18-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;ансамбль (случайный лес)&quot;</span>:</span>\n<span id="cb18-10"><a href="#cb18-10" aria-hidden="true" tabindex="-1"></a>        (Pipeline([(<span class="st">&quot;clf&quot;</span>, RandomForestClassifier(random_state<span class="op">=</span>RANDOM_STATE))]),</span>\n<span id="cb18-11"><a href="#cb18-11" aria-hidden="true" tabindex="-1"></a>         {<span class="st">&quot;clf__n_estimators&quot;</span>: [<span class="dv">200</span>], <span class="st">&quot;clf__max_features&quot;</span>: [<span class="st">&quot;sqrt&quot;</span>, <span class="fl">0.5</span>],</span>\n<span id="cb18-12"><a href="#cb18-12" aria-hidden="true" tabindex="-1"></a>          <span class="st">&quot;clf__max_depth&quot;</span>: [<span class="dv">5</span>, <span class="dv">12</span>, <span class="va">None</span>]}),</span>\n<span id="cb18-13"><a href="#cb18-13" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb18-14"><a href="#cb18-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb18-15"><a href="#cb18-15" aria-hidden="true" tabindex="-1"></a>rows, fitted <span class="op">=</span> [], {}</span>\n<span id="cb18-16"><a href="#cb18-16" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> nm, (pipe, grid) <span class="kw">in</span> candidates.items():</span>\n<span id="cb18-17"><a href="#cb18-17" aria-hidden="true" tabindex="-1"></a>    gs <span class="op">=</span> GridSearchCV(pipe, grid, cv<span class="op">=</span>cvf, scoring<span class="op">=</span><span class="st">&quot;roc_auc&quot;</span>, n_jobs<span class="op">=-</span><span class="dv">1</span>).fit(Xtr, ytr)</span>\n<span id="cb18-18"><a href="#cb18-18" aria-hidden="true" tabindex="-1"></a>    fitted[nm] <span class="op">=</span> gs.best_estimator_</span>\n<span id="cb18-19"><a href="#cb18-19" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;модель&quot;</span>: nm, <span class="st">&quot;CV AUC&quot;</span>: gs.best_score_,</span>\n<span id="cb18-20"><a href="#cb18-20" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;AUC на контроле&quot;</span>: roc_auc_score(yte, gs.predict_proba(Xte)[:, <span class="dv">1</span>])})</span>\n<span id="cb18-21"><a href="#cb18-21" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>nm<span class="sc">}</span><span class="ss">: </span><span class="sc">{</span>gs<span class="sc">.</span>best_params_<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb18-22"><a href="#cb18-22" aria-hidden="true" tabindex="-1"></a>rows.append({<span class="st">&quot;модель&quot;</span>: <span class="st">&quot;константа&quot;</span>, <span class="st">&quot;CV AUC&quot;</span>: <span class="fl">0.5</span>, <span class="st">&quot;AUC на контроле&quot;</span>: <span class="fl">0.5</span>})</span>\n<span id="cb18-23"><a href="#cb18-23" aria-hidden="true" tabindex="-1"></a>final <span class="op">=</span> pd.DataFrame(rows).set_index(<span class="st">&quot;модель&quot;</span>)</span>\n<span id="cb18-24"><a href="#cb18-24" aria-hidden="true" tabindex="-1"></a>display(final.<span class="bu">round</span>(<span class="dv">4</span>))</span></code></pre></div>\n</div>\n<div id="cell034" class="cell code">\n<div class="sourceCode" id="cb19"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb19-1"><a href="#cb19-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.inspection <span class="im">import</span> permutation_importance</span>\n<span id="cb19-2"><a href="#cb19-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb19-3"><a href="#cb19-3" aria-hidden="true" tabindex="-1"></a>best_name <span class="op">=</span> final.drop(index<span class="op">=</span><span class="st">&quot;константа&quot;</span>)[<span class="st">&quot;CV AUC&quot;</span>].idxmax()</span>\n<span id="cb19-4"><a href="#cb19-4" aria-hidden="true" tabindex="-1"></a>perm <span class="op">=</span> permutation_importance(fitted[best_name], Xte, yte, n_repeats<span class="op">=</span><span class="dv">15</span>,</span>\n<span id="cb19-5"><a href="#cb19-5" aria-hidden="true" tabindex="-1"></a>                              random_state<span class="op">=</span><span class="dv">0</span>, scoring<span class="op">=</span><span class="st">&quot;roc_auc&quot;</span>)</span>\n<span id="cb19-6"><a href="#cb19-6" aria-hidden="true" tabindex="-1"></a>imp <span class="op">=</span> pd.Series(perm.importances_mean, index<span class="op">=</span>data[<span class="st">&quot;feature_names&quot;</span>]).nlargest(<span class="dv">10</span>)</span>\n<span id="cb19-7"><a href="#cb19-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb19-8"><a href="#cb19-8" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots(figsize<span class="op">=</span>(<span class="dv">8</span>, <span class="fl">4.5</span>))</span>\n<span id="cb19-9"><a href="#cb19-9" aria-hidden="true" tabindex="-1"></a>imp[::<span class="op">-</span><span class="dv">1</span>].plot.barh(ax<span class="op">=</span>ax, color<span class="op">=</span><span class="st">&quot;#128C7E&quot;</span>)</span>\n<span id="cb19-10"><a href="#cb19-10" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="st">&quot;падение ROC-AUC при перестановке признака&quot;</span>)</span>\n<span id="cb19-11"><a href="#cb19-11" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="ss">f&quot;Что определяет предсказание: </span><span class="sc">{</span>best_name<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb19-12"><a href="#cb19-12" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell035" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какая модель победила и насколько уверенно?\nПомог ли PCA? Согласуется ли важность признаков с предметной\nобластью?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell036" class="cell markdown">\n<h2 id="итоги-занятия">Итоги занятия</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Первая главная компонента — собственный вектор\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nс наибольшим собственным числом. Почему именно наибольшим? Изложите\nрассуждение теоремы 8.2 своими словами.</li>\n<li>PCA не использует метки классов. Постройте пример двух классов в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>ℝ</mi><mn>2</mn></msup><annotation encoding="application/x-tex">\\mathbb{R}^2</annotation></semantics></math>,\nдля которых проекция на первую главную компоненту полностью уничтожает\nразделимость.</li>\n<li>У вас есть только матрица попарных несходств между 200 объектами,\nкоординат нет. Какие методы курса вы можете применить, а какие —\nнет?</li>\n<li>Оглядываясь на весь курс: назовите три проверки, которые вы теперь\nбудете делать всегда, прежде чем поверить в качество модели.</li>\n</ol>\n<hr />\n<p><strong>Дома:</strong> откройте <code>lab09_homework.ipynb</code> —\nтам две задачи: PCA двумя способами (и почему на практике всегда SVD) и\nвыбор числа компонент по качеству, а не по дисперсии.</p>\n</div>\n</body>\n</html>\n'}}]);